fn base(d:usize,i:usize)->usize{2+d+i*(d+2)}
fn validate(v:&[i64],d:usize,n:usize,i:i64,seen:&mut[bool;15],reached:&mut usize)->bool{if i<0{return true}let j=i as usize;if j>=n||seen[j]{return false}seen[j]=true;*reached+=1;let b=base(d,j);let l=v[b+d];let r=v[b+d+1];if l>=0&&l==r{return false}validate(v,d,n,l,seen,reached)&&validate(v,d,n,r,seen,reached)}
fn search(v:&[i64],d:usize,i:i64,depth:usize,q:&[i64;3],best:&mut[i64;3],bestd:&mut i64,visited:&mut i64){if i<0{return}*visited+=1;let b=base(d,i as usize);let mut dist=0;for k in 0..d{let z=q[k]-v[b+k];dist+=z*z}if dist<*bestd{*bestd=dist;for k in 0..d{best[k]=v[b+k]}}let axis=depth%d;let(l,r)=(v[b+d],v[b+d+1]);let(near,far)=if q[axis]<=v[b+axis]{(l,r)}else{(r,l)};search(v,d,near,depth+1,q,best,bestd,visited);let split=q[axis]-v[b+axis];if split*split<*bestd{search(v,d,far,depth+1,q,best,bestd,visited)}}
#[no_mangle]
pub unsafe extern "C" fn nearest_neighbour_search(v:*const i64,n:usize,out:*mut u8,cap:usize)->i64{if v.is_null()||n<5{return -1}let d0=*v;let n0=*v.add(1);if (d0!=2&&d0!=3)||!(1..=15).contains(&n0){return -1}let d=d0 as usize;let count=n0 as usize;if n!=2+d+count*(d+2){return -1}let vals=std::slice::from_raw_parts(v,n);let mut q=[0;3];for k in 0..d{q[k]=vals[2+k];if !(-1000..=1000).contains(&q[k]){return -1}}for i in 0..count{let b=base(d,i);for k in 0..d{if !(-1000..=1000).contains(&vals[b+k]){return -1}}let l=vals[b+d];let r=vals[b+d+1];if l < -1||l>=n0||r < -1||r>=n0||(l>=0&&l==r){return -1}}let mut seen=[false;15];let mut reached=0;if !validate(vals,d,count,0,&mut seen,&mut reached)||reached!=count{return -1}let mut best=[0;3];let mut bestd=i64::MAX;let mut visited=0;search(vals,d,0,0,&q,&mut best,&mut bestd,&mut visited);if out.is_null()||cap<48{return -2}let result=[d0,best[0],best[1],if d==3{best[2]}else{0},bestd,visited];for(i,x)in result.iter().enumerate(){let b=x.to_le_bytes();for k in 0..8{*out.add(i*8+k)=b[k];}}48}
